import{_ as s,o as i,c as t,ag as a}from"./chunks/framework.BSwSpTvy.js";const m=JSON.parse('{"title":"🎭 System Prompts & Persona","description":"","frontmatter":{},"headers":[],"relativePath":"features/system-prompts.md","filePath":"features/system-prompts.md"}'),n={name:"features/system-prompts.md"};function o(r,e,l,h,p,d){return i(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="🎭-system-prompts-persona" tabindex="-1">🎭 System Prompts &amp; Persona <a class="header-anchor" href="#🎭-system-prompts-persona" aria-label="Permalink to &quot;🎭 System Prompts &amp; Persona&quot;">​</a></h1><p>The System Prompt is the agent&#39;s &quot;subconscious&quot;—a set of foundational instructions that define its identity, its available tools, and its behavioral boundaries.</p><h2 id="the-handlebars-engine" tabindex="-1">The Handlebars Engine <a class="header-anchor" href="#the-handlebars-engine" aria-label="Permalink to &quot;The Handlebars Engine&quot;">​</a></h2><p>Instead of a static text file, this fork uses the <strong>Handlebars</strong> template engine to dynamically construct the prompt based on your real-time environment.</p><p>The template is located in <code>crates/agent/src/templates/system_prompt.hbs</code> and is embedded into the binary using <code>rust-embed</code> for maximum performance.</p><h2 id="prompt-prioritization-top-to-bottom" tabindex="-1">Prompt Prioritization (Top to Bottom) <a class="header-anchor" href="#prompt-prioritization-top-to-bottom" aria-label="Permalink to &quot;Prompt Prioritization (Top to Bottom)&quot;">​</a></h2><p>The prompt is structured into five distinct sections, prioritized by their distance from the user&#39;s latest query:</p><ol><li><strong>Identity &amp; Persona</strong>: Defines the agent as a &quot;10x proactive engineer&quot; who uses <code>&lt;thought&gt;</code> blocks.</li><li><strong>Epistemic State</strong>: Dynamic sensors providing real-time data on active files and LSP error counts.</li><li><strong>Language Modifiers</strong>: Targeted best practices injected based on the file extension (e.g., C++17 pointers).</li><li><strong>Project Memory</strong>: Contextually relevant facts retrieved from the <a href="/zed-custom/features/memory.html">SQLite database</a>.</li><li><strong>Custom Session Instructions</strong>: Thread-specific overrides set via the ✨ GUI, injected after memory.</li><li><strong>Custom Rules</strong>: Your project-scoped <code>.rules</code> files, placed last to maximize the model&#39;s attention.</li></ol><h2 id="dynamic-session-overrides" tabindex="-1">Dynamic Session Overrides <a class="header-anchor" href="#dynamic-session-overrides" aria-label="Permalink to &quot;Dynamic Session Overrides&quot;">​</a></h2><p>Unlike binary-embedded templates or project-wide <code>.rules</code> files, <strong>Custom Session Instructions</strong> allow you to pivot the agent&#39;s behavior for just the current thread.</p><p>Click the ✨ icon in the message editor toolbar to open a modal where you can paste specific constraints like &quot;Write all tests in Jest&quot; or &quot;Respond as if you are a code reviewer.&quot; These are injected into every system prompt refresh for that session.</p><h2 id="technical-detail-memory-injection" tabindex="-1">Technical Detail: Memory Injection <a class="header-anchor" href="#technical-detail-memory-injection" aria-label="Permalink to &quot;Technical Detail: Memory Injection&quot;">​</a></h2><p>The memory block is injected using a conditional Handlebars loop that iterates through your project&#39;s historical facts:</p><div class="language-hbs vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">hbs</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{{</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">gt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">len</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> memories</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">## Project Memory</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">The following information has been remembered from previous sessions:</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{{</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#each</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> memories</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">### \\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{{</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">category</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{{</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">content</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{{</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/each</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{{</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/if</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}}</span></span></code></pre></div><h2 id="modifying-the-persona" tabindex="-1">Modifying the Persona <a class="header-anchor" href="#modifying-the-persona" aria-label="Permalink to &quot;Modifying the Persona&quot;">​</a></h2><p>Because the prompt is embedded in the binary, fundamental changes to the agent&#39;s base persona require editing the <code>.hbs</code> template and re-running <code>cargo build --release</code>.</p><p>For transient project-specific behaviors, we recommend using <a href="/zed-custom/features/rules.html">Custom Rules</a> instead of binary modifications.</p><h2 id="workflow-impact" tabindex="-1">Workflow Impact <a class="header-anchor" href="#workflow-impact" aria-label="Permalink to &quot;Workflow Impact&quot;">​</a></h2><ul><li><strong>Absolute Control</strong>: You own the prompt. If the agent is being too chatty or making formatting errors, you can fix its &quot;brain&quot; directly without waiting for an upstream Zed release.</li><li><strong>Model Optimization</strong>: Fine-tune the context injection strategy based on whether you&#39;re using Claude 3.5 Sonnet, GPT-4o, or local Llama models.</li><li><strong>Security &amp; Privacy</strong>: Audit exactly what system-level metadata is being leaked to the model and strip out what you don&#39;t want.</li><li><strong>Rapid Prototyping</strong>: Experiment with new agent capabilities (like &quot;Refactor Mode&quot;) by simply creating a new Handlebars template.</li></ul>`,19)])])}const k=s(n,[["render",o]]);export{m as __pageData,k as default};
